def _snapshot_disk_usage(output_path: str) -> None:
    """Append a disk usage snapshot as a JSONL line. Scans key directories."""
    import subprocess
    snapshot = {"ts": time.strftime("%H:%M:%S", time.gmtime()), "epoch": time.time()}

    # df for overall filesystem usage
    try:
        df = subprocess.run(["df", "-h"], capture_output=True, text=True, timeout=5)
        snapshot["df"] = df.stdout
    except Exception:
        pass

    # Per-directory sizes for key paths
    for d in ["/mnt/workspace", "/mnt", "/app", "/tmp"]:
        if os.path.isdir(d):
            try:
                du = subprocess.run(
                    ["du", "-sh", "--max-depth=2", d],
                    capture_output=True, text=True, timeout=10,
                )
                snapshot[f"du_{d.replace('/', '_').strip('_')}"] = du.stdout
            except Exception:
                pass

    # Strands session file specifically
    sessions_dir = os.path.join(WORKSPACE_DIR, ".sessions")
    if os.path.isdir(sessions_dir):
        try:
            total = 0
            files = []
            for root, _, fnames in os.walk(sessions_dir):
                for fn in fnames:
                    fp = os.path.join(root, fn)
                    sz = os.path.getsize(fp)
                    total += sz
                    files.append(f"{fp}: {sz/1024/1024:.2f}MB")
            snapshot["sessions_total_mb"] = round(total / 1024 / 1024, 2)
            snapshot["session_files"] = files[:20]
        except Exception:
            pass

    with open(output_path, "a") as f:
        f.write(json.dumps(snapshot, default=str) + "\n")


